from __future__ import annotations

from typing import Any


class NotificationGateway:
    def __init__(self) -> None:
        self._deliveries: list[dict[str, Any]] = []

    def send_email(self, user_id: str, subject: str, body: str) -> dict[str, Any]:
        payload = {
            "channel": "email",
            "user_id": user_id.strip(),
            "subject": subject,
            "body": body,
            "ok": True,
        }
        self._deliveries.append(payload)
        return dict(payload)

    def send_sms(self, user_id: str, body: str) -> dict[str, Any]:
        payload = {
            "channel": "sms",
            "user_id": user_id.strip(),
            "subject": "",
            "body": body,
            "ok": True,
        }
        self._deliveries.append(payload)
        return dict(payload)

    def send_push(self, user_id: str, title: str, body: str) -> dict[str, Any]:
        payload = {
            "channel": "push",
            "user_id": user_id.strip(),
            "subject": title,
            "body": body,
            "ok": True,
        }
        self._deliveries.append(payload)
        return dict(payload)

    def list_deliveries(self) -> list[dict[str, Any]]:
        return [dict(item) for item in self._deliveries]

    def count(self) -> int:
        return len(self._deliveries)

    def clear(self) -> None:
        self._deliveries.clear()


def build_message(order: dict[str, Any], event_type: str) -> dict[str, str]:
    order_id = str(order.get("order_id", "")).strip()
    amount_cents = int(order.get("amount_cents", 0))
    amount_text = f"${amount_cents / 100:.2f}"
    status = str(order.get("status", "")).strip().lower()

    if event_type == "order_paid":
        return {
            "subject": f"Order {order_id} payment confirmed",
            "body": f"Your payment of {amount_text} has been confirmed.",
            "push_title": "Payment confirmed",
        }
    if event_type == "order_fulfilled":
        return {
            "subject": f"Order {order_id} fulfilled",
            "body": f"Your order is now fulfilled. Status is {status}.",
            "push_title": "Order fulfilled",
        }
    if event_type == "order_canceled":
        return {
            "subject": f"Order {order_id} canceled",
            "body": f"Your order was canceled. If this is unexpected, contact support.",
            "push_title": "Order canceled",
        }
    return {
        "subject": f"Order {order_id} updated",
        "body": f"Order status changed to {status}.",
        "push_title": "Order update",
    }


def route_channel(preferred_channel: str, event_type: str) -> str:
    normalized = preferred_channel.strip().lower()
    if normalized not in {"email", "sms", "push"}:
        normalized = "email"
    if event_type == "order_canceled" and normalized == "push":
        return "email"
    return normalized

