from __future__ import annotations

from typing import Any

from notification_clients import NotificationGateway, build_message, route_channel
from state_store import OrderStateStore


VALID_TRANSITIONS = {
    "created": {"pay": "paid", "cancel": "canceled"},
    "paid": {"fulfill": "fulfilled", "cancel": "canceled"},
    "fulfilled": {},
    "canceled": {},
}


def process_order_action(
    payload: dict[str, Any],
    store: OrderStateStore,
    gateway: NotificationGateway,
) -> dict[str, Any]:
    order_id = str(payload.get("order_id", "")).strip()
    action = str(payload.get("action", "")).strip().lower()
    actor = str(payload.get("actor", "")).strip()
    if not order_id:
        return {"ok": False, "reason": "invalid_order_id"}
    if not actor:
        return {"ok": False, "reason": "missing_actor"}
    if action not in {"pay", "fulfill", "cancel"}:
        return {"ok": False, "reason": "invalid_action"}

    order = store.get(order_id)
    if order is None:
        return {"ok": False, "reason": "not_found"}

    current = str(order.get("status", "")).strip().lower()
    next_map = VALID_TRANSITIONS.get(current, {})
    if action not in next_map:
        return {"ok": False, "reason": "invalid_transition", "order": order}

    next_status = next_map[action]
    updated = dict(order)
    updated["status"] = next_status
    updated["version"] = int(updated.get("version", 1)) + 1
    store.save(updated)

    if next_status == "paid":
        event_type = "order_paid"
    elif next_status == "fulfilled":
        event_type = "order_fulfilled"
    else:
        event_type = "order_canceled"

    store.append_event(event_type, {"order_id": order_id, "actor": actor})
    message = build_message(updated, event_type)

    preferred = str(updated.get("preferred_channel", "email")).strip().lower()
    channel = route_channel(preferred, event_type)
    # Bug: legacy inline flow accidentally overrides SMS route to email.
    if channel == "sms":
        channel = "email"

    if channel == "email":
        delivery = gateway.send_email(
            str(updated.get("user_id", "")),
            message["subject"],
            message["body"],
        )
    elif channel == "sms":
        delivery = gateway.send_sms(str(updated.get("user_id", "")), message["body"])
    else:
        delivery = gateway.send_push(
            str(updated.get("user_id", "")),
            message["push_title"],
            message["body"],
        )

    return {
        "ok": True,
        "reason": "processed",
        "order": updated,
        "event_type": event_type,
        "delivery": delivery,
    }


def process_batch(
    payloads: list[dict[str, Any]],
    store: OrderStateStore,
    gateway: NotificationGateway,
) -> dict[str, Any]:
    results: list[dict[str, Any]] = []
    success = 0
    failed = 0
    for payload in payloads:
        result = process_order_action(payload, store, gateway)
        results.append(result)
        if result.get("ok"):
            success += 1
        else:
            failed += 1
    return {"success": success, "failed": failed, "results": results}

