from __future__ import annotations

from typing import Any


class OrderStateStore:
    def __init__(self) -> None:
        self._orders: dict[str, dict[str, Any]] = {}
        self._events: list[dict[str, Any]] = []

    def seed(self, records: list[dict[str, Any]]) -> None:
        self._orders.clear()
        self._events.clear()
        for item in records:
            order_id = str(item.get("order_id", "")).strip()
            if not order_id:
                raise ValueError("order_id is required")
            status = str(item.get("status", "created")).strip().lower()
            if status not in {"created", "paid", "fulfilled", "canceled"}:
                raise ValueError("invalid status")
            self._orders[order_id] = {
                "order_id": order_id,
                "user_id": str(item.get("user_id", "")).strip(),
                "amount_cents": int(item.get("amount_cents", 0)),
                "status": status,
                "version": int(item.get("version", 1)),
                "preferred_channel": str(item.get("preferred_channel", "email")).strip().lower(),
            }

    def get(self, order_id: str) -> dict[str, Any] | None:
        key = order_id.strip()
        if not key:
            return None
        item = self._orders.get(key)
        if item is None:
            return None
        return dict(item)

    def save(self, order: dict[str, Any]) -> None:
        order_id = str(order.get("order_id", "")).strip()
        if not order_id:
            raise ValueError("order_id is required")
        status = str(order.get("status", "")).strip().lower()
        if status not in {"created", "paid", "fulfilled", "canceled"}:
            raise ValueError("invalid status")
        self._orders[order_id] = {
            "order_id": order_id,
            "user_id": str(order.get("user_id", "")).strip(),
            "amount_cents": int(order.get("amount_cents", 0)),
            "status": status,
            "version": int(order.get("version", 1)),
            "preferred_channel": str(order.get("preferred_channel", "email")).strip().lower(),
        }

    def append_event(self, event_type: str, payload: dict[str, Any]) -> None:
        self._events.append(
            {
                "event_type": event_type.strip() or "unknown",
                "payload": dict(payload),
            }
        )

    def list_events(self) -> list[dict[str, Any]]:
        return [dict(item) for item in self._events]

    def events_by_type(self, event_type: str) -> list[dict[str, Any]]:
        target = event_type.strip()
        return [item for item in self._events if item.get("event_type") == target]

    def order_count(self) -> int:
        return len(self._orders)

    def event_count(self) -> int:
        return len(self._events)

    def snapshot(self) -> dict[str, Any]:
        return {
            "orders": {key: dict(value) for key, value in self._orders.items()},
            "event_count": len(self._events),
        }

    def clear_events(self) -> None:
        self._events.clear()

